// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this) && actor != address(0));
        vm.assume(newOwner != address(0));
        // Record admin to check actor is not admin
        address admin = c.owner(); // constructor sets owner = msg.sender (admin)
        vm.assume(actor != admin);
        vm.prank(actor);
        c.setOwner(newOwner);
        // After a non-admin call, owner must remain unchanged (initial admin)
        assertTrue(c.owner() == admin);
    }
}
